from __future__ import annotations
import csv, json, math, os, re, statistics, sys
from dataclasses import asdict, dataclass
from datetime import datetime, timezone
from pathlib import Path
from typing import Iterator
FIELDS = ('repo_id','tenant_id','language','runtime_major','dependency_count','critical_cves','build_minutes','observed_at')
@dataclass(frozen=True)
class Row:
    repo_id: str
    tenant_id: str
    language: str
    runtime_major: int
    dependency_count: int
    critical_cves: int
    build_minutes: float
    observed_at: datetime

def integer(value: str, minimum: int) -> int:
    if not re.fullmatch(r'[0-9]+', value):
        raise ValueError('integer required')
    result = int(value)
    if result < minimum or result > 2**31-1:
        raise ValueError('integer outside supported range')
    return result

def normalize(raw: dict[str,str]) -> Row:
    values = {k: (raw.get(k) or '').strip() for k in FIELDS}
    if any(not v for v in values.values()):
        raise ValueError('required field missing')
    if values['language'] not in {'java','dotnet'}:
        raise ValueError('unsupported language')
    duration = float(values['build_minutes'])
    if not math.isfinite(duration) or duration < 0:
        raise ValueError('build duration must be finite and nonnegative')
    observed = datetime.fromisoformat(values['observed_at'].replace('Z','+00:00'))
    if observed.tzinfo is None:
        raise ValueError('timestamp must include timezone')
    return Row(values['repo_id'], values['tenant_id'], values['language'],
               integer(values['runtime_major'],1), integer(values['dependency_count'],0),
               integer(values['critical_cves'],0), duration, observed.astimezone(timezone.utc))

def ingest(path: Path) -> Iterator[tuple[int,Row|None,str|None]]:
    with path.open(newline='', encoding='utf-8') as handle:
        reader = csv.DictReader(handle)
        if reader.fieldnames is None:
            return
        if set(FIELDS)-set(reader.fieldnames):
            raise ValueError('CSV header missing required columns')
        for line, raw in enumerate(reader,2):
            try:
                if None in raw:
                    raise ValueError('extra CSV fields')
                yield line, normalize(raw), None
            except (ValueError,TypeError,OverflowError) as exc:
                yield line, None, str(exc)

def report(path: Path) -> dict:
    latest: dict[tuple[str,str], tuple[int,Row]] = {}
    invalid, superseded = [], []
    total = valid = 0
    for line, row, error in ingest(path):
        total += 1
        if row is None:
            invalid.append({'line':line,'reason':error}); continue
        valid += 1
        key = (row.tenant_id,row.repo_id)
        previous = latest.get(key)
        if previous is None:
            latest[key]=(line,row)
        elif row.observed_at > previous[1].observed_at:
            superseded.append({'line':previous[0],'retained_line':line})
            latest[key]=(line,row)
        else:
            superseded.append({'line':line,'retained_line':previous[0]})
    rows = [r for _,r in latest.values()]
    summary = {}
    for tenant in sorted({r.tenant_id for r in rows}):
        durations = [r.build_minutes for r in rows if r.tenant_id==tenant]
        summary[tenant]={'count':len(durations),'mean':statistics.mean(durations),
                         'median':statistics.median(durations)}
    assert total == valid + len(invalid)
    assert valid == len(rows) + len(superseded)
    normalized=[]
    for row in rows:
        item=asdict(row); item['observed_at']=row.observed_at.isoformat()
        normalized.append(item)
    return {'counts':{'total':total,'valid':valid,'invalid':len(invalid),
                      'retained':len(rows),'superseded':len(superseded)},
            'invalid':invalid,'superseded':superseded,'tenants':summary,'rows':normalized}

def optional_parity(result: dict) -> None:
    import numpy as np
    import pandas as pd
    frame=pd.DataFrame(result['rows'])
    if frame.empty: return
    for tenant, expected in result['tenants'].items():
        values=frame.loc[frame.tenant_id==tenant,'build_minutes'].to_numpy()
        assert math.isclose(float(np.mean(values)),expected['mean'])
    grouped=frame.groupby('tenant_id').build_minutes.agg(['size','mean','median'])
    for tenant, expected in result['tenants'].items():
        assert int(grouped.loc[tenant,'size'])==expected['count']
        assert math.isclose(float(grouped.loc[tenant,'median']),expected['median'])

if __name__=='__main__':
    if len(sys.argv)!=3: raise SystemExit('usage: python day01_inventory.py inventory.csv report.json')
    source=Path(sys.argv[1]); destination=Path(sys.argv[2])
    if source.resolve()==destination.resolve(): raise SystemExit('output must differ from input')
    result=report(source)
    tmp=destination.with_suffix(destination.suffix+'.tmp')
    tmp.write_text(json.dumps(result,indent=2,allow_nan=False),encoding='utf-8')
    os.replace(tmp,destination)
    print(json.dumps(result['counts']))

from __future__ import annotations
import json, multiprocessing as mp, time, math
from dataclasses import dataclass
@dataclass(frozen=True)
class Request:
    tenant: str
    evidence: tuple[dict,...]
    context: str
    max_output: int=80

def provider(request: Request) -> dict:
    runtime=next(e for e in request.evidence if e['kind']=='java_runtime')
    return {'action':'assess_java_upgrade','current_runtime':runtime['value'],
            'evidence_ids':[runtime['id']], 'status':'proposal',
            'input_units':len(request.context.split()),'output_units':24,'provider':'offline_stub'}
def child(request,queue,delay):
    time.sleep(delay)
    queue.put(provider(request))
def invoke(request,timeout=.5,delay=0.):
    ctx=mp.get_context('spawn'); queue=ctx.Queue()
    process=ctx.Process(target=child,args=(request,queue,delay))
    process.start()
    try:
        result=queue.get(timeout=timeout)
    except Exception as exc:
        process.terminate(); process.join()
        raise TimeoutError('offline provider deadline exceeded') from exc
    finally:
        if process.is_alive(): process.join(timeout=.1)
        if process.is_alive(): process.terminate(); process.join()
        queue.close()
    return result

def validate(request,result):
    required={'action','current_runtime','evidence_ids','status','input_units','output_units','provider'}
    if set(result)!=required: raise ValueError('response schema mismatch')
    if result['action']!='assess_java_upgrade' or result['status']!='proposal': raise ValueError('unsupported action')
    evidence={e['id']:e for e in request.evidence}
    ids=result['evidence_ids']
    if not isinstance(ids,list) or not ids or any(not isinstance(i,str) or i not in evidence for i in ids):
        raise ValueError('unsupported citation')
    runtime=result['current_runtime']
    if type(runtime) is not int or not any(evidence[i]['kind']=='java_runtime' and evidence[i]['value']==runtime for i in ids):
        raise ValueError('runtime claim not supported by citation')
    for name,cap in [('input_units',len(request.context.split())),('output_units',request.max_output)]:
        if type(result[name]) is not int or not 0<=result[name]<=cap: raise ValueError('usage outside cap')

class Gateway:
    # Teaching unit prices, not current vendor prices; single-process ledger only.
    INPUT_PRICE=.00001; OUTPUT_PRICE=.00002
    def __init__(self): self.balances={'tenant-a':1.0}
    def recommend(self,request,delay=0.):
        if request.tenant not in self.balances: raise PermissionError('unknown tenant')
        if request.max_output<24 or request.max_output>100: raise ValueError('output cap outside policy')
        if not request.evidence or any(e.get('tenant')!=request.tenant for e in request.evidence): raise PermissionError('cross-tenant evidence')
        maximum=len(request.context.split())*self.INPUT_PRICE+request.max_output*self.OUTPUT_PRICE
        if maximum>self.balances[request.tenant]: raise ValueError('budget exceeded before execution')
        self.balances[request.tenant]-=maximum
        try:
            result=invoke(request,delay=delay); validate(request,result)
            actual=result['input_units']*self.INPUT_PRICE+result['output_units']*self.OUTPUT_PRICE
            self.balances[request.tenant]+=maximum-actual
            return result,actual
        except Exception:
            self.balances[request.tenant]+=maximum
            raise

def percentile95(values):
    ordered=sorted(values); return ordered[max(0,math.ceil(.95*len(ordered))-1)]
if __name__=='__main__':
    gateway=Gateway(); reports={}
    for configuration in ['full','selected']:
        latencies=[]; units=0; cost=0.; passed=0
        for task in range(20):
            evidence=({'id':f'runtime-{task}','kind':'java_runtime','value':17,'tenant':'tenant-a'},)
            context='runtime 17' + (' irrelevant fixture details'*80 if configuration=='full' else '')
            request=Request('tenant-a',evidence,context)
            start=time.perf_counter(); result,charged=gateway.recommend(request)
            latencies.append((time.perf_counter()-start)*1000); units+=result['input_units']+result['output_units']; cost+=charged
            passed+=result['current_runtime']==17
        reports[configuration]={'provider':'offline_stub','supported_fixtures':passed,'total_fixtures':20,
                                'p95_stub_ms':percentile95(latencies),'estimated_units':units,'teaching_cost':cost}
    request=Request('tenant-a',({'id':'runtime','kind':'java_runtime','value':17,'tenant':'tenant-a'},),'runtime 17')
    forged=provider(request); forged['evidence_ids']=['missing']
    try: validate(request,forged)
    except ValueError: pass
    else: raise AssertionError('forged citation accepted')
    gateway.balances['tenant-a']=0.
    try: gateway.recommend(request)
    except ValueError: pass
    else: raise AssertionError('budget bypass')
    gateway.balances['tenant-a']=1.
    try: gateway.recommend(request,delay=1.)
    except TimeoutError: pass
    else: raise AssertionError('deadline missing')
    print(json.dumps(reports,indent=2)); print('citation, budget and timeout negative checks passed')

from __future__ import annotations
import json,re
from dataclasses import dataclass
@dataclass(frozen=True)
class Document:
    id: str
    tenant: str
    roles: frozenset[str]
    text: str
    source: str
    version: str

def tokens(text): return set(re.findall(r'[a-z0-9_]+',text.lower()))
DOCS=[Document(f'{tenant}-note-{i}',tenant,frozenset({'engineer'}),
      f'repository repo_{i} migration topic_{i} runtime {17+i%2} contract serialization endpoint api_{i}',
      f'notes/repo_{i}.md','fixture-v1') for tenant in ['tenant-a','tenant-b'] for i in range(15)]
QUERIES=[{'id':f'q-{tenant}-{i}','tenant':tenant,'roles':['engineer'],
          'query':f'repo_{i} topic_{i} api_{i}','relevant':[f'{tenant}-note-{i}']}
         for tenant in ['tenant-a','tenant-b'] for i in range(15)]

def retrieve(query,tenant,roles,k=3):
    if not tenant or k<1 or k>10: raise ValueError('invalid retrieval request')
    authorized=[d for d in DOCS if d.tenant==tenant and d.roles&set(roles)]
    wanted=tokens(query)
    ranked=sorted(authorized,key=lambda d:(-len(wanted&tokens(d.text)),d.id))
    hits=[d for d in ranked if wanted&tokens(d.text)][:k]
    assert all(d.tenant==tenant and d.roles&set(roles) for d in hits)
    return hits

def evaluate(k):
    cases=[]
    for fixture in QUERIES:
        hits=retrieve(fixture['query'],fixture['tenant'],fixture['roles'],k)
        found={d.id for d in hits}; relevant=set(fixture['relevant'])
        if not relevant: raise ValueError('query missing relevance labels')
        recall=len(found&relevant)/len(relevant)
        cases.append({'query_id':fixture['id'],'retrieved':sorted(found),'recall':recall})
    return {'method':'lexical token overlap; no semantic embeddings','k':k,
      'documents':len(DOCS),'queries':len(cases),'macro_recall':sum(c['recall'] for c in cases)/len(cases),
      'failures':[c for c in cases if c['recall']<1]}
if __name__=='__main__':
    assert len(DOCS)==30 and len(QUERIES)==30
    for fixture in QUERIES:
        assert all(d.tenant==fixture['tenant'] for d in retrieve(fixture['query'],fixture['tenant'],fixture['roles']))
    assert retrieve('repo_0','tenant-a',['viewer'])==[]
    assert retrieve('repo_0','tenant-unknown',['engineer'])==[]
    assert {d.id for d in retrieve('repo_0','tenant-a',['engineer'])}=={'tenant-a-note-0'}
    print(json.dumps([evaluate(k) for k in [1,3,5]],indent=2))
    print('ACL negative checks passed; synthesis/faithfulness unassessed')

from __future__ import annotations
import hashlib,json,tempfile
from pathlib import Path
from dataclasses import dataclass
from enum import Enum
class Stage(str,Enum):
    INSPECT='inspect'; PLAN='plan'; APPROVED='approved'; PATCHED='patched'; CHECKED='checked'; REPORT='report'; BLOCKED='blocked'
@dataclass(frozen=True)
class Proposal:
    path: str
    before: str
    after: str
    source_hash: str
    def digest(self):
        return hashlib.sha256(json.dumps(self.__dict__,sort_keys=True).encode()).hexdigest()
def digest(data): return hashlib.sha256(data).hexdigest()
class Workflow:
    def __init__(self,root):
        self.root=Path(root).resolve(); self.stage=Stage.INSPECT; self.steps=0; self.maximum=8
        self.receipts={}; self.approval=None; self.proposal=None
    def tick(self):
        self.steps+=1
        if self.steps>self.maximum: self.stage=Stage.BLOCKED; raise RuntimeError('step budget exhausted')
    def file(self,relative):
        if relative!='Fixture.java': raise PermissionError('file outside approved scope')
        path=self.root/relative
        if path.is_symlink(): raise PermissionError('symlink denied')
        resolved=path.resolve()
        if not resolved.is_relative_to(self.root): raise PermissionError('path escape')
        return resolved
    def inspect(self):
        self.tick(); path=self.file('Fixture.java'); data=path.read_bytes()
        if len(data)>8192: raise ValueError('read cap exceeded')
        return {'source_hash':digest(data),'bytes':len(data),'unresolved_edges':['reflection not analyzed']}
    def plan(self):
        if self.stage!=Stage.INSPECT: raise RuntimeError('invalid transition')
        evidence=self.inspect(); self.tick()
        self.proposal=Proposal('Fixture.java','return 1;','return 2;',evidence['source_hash'])
        self.stage=Stage.PLAN; return self.proposal
    def approve(self,reviewed_digest):
        self.tick()
        if self.stage!=Stage.PLAN or reviewed_digest!=self.proposal.digest(): raise PermissionError('approval mismatch')
        self.approval=reviewed_digest; self.stage=Stage.APPROVED
    def apply(self):
        self.tick(); proposal=self.proposal; key=proposal.digest()
        if key in self.receipts:
            if digest(self.file(proposal.path).read_bytes())!=self.receipts[key]['output_hash']:
                raise PermissionError('replay artifact drift')
            return self.receipts[key]
        if self.stage!=Stage.APPROVED or key!=self.approval: raise PermissionError('missing or stale approval')
        path=self.file(proposal.path); data=path.read_bytes()
        if digest(data)!=proposal.source_hash: raise PermissionError('source changed since approval')
        text=data.decode()
        if text.count(proposal.before)!=1: raise ValueError('patch precondition failed')
        changed=text.replace(proposal.before,proposal.after,1)
        if len(changed.encode())>8192: raise ValueError('write cap exceeded')
        path.write_text(changed)
        receipt={'action':'local_fixture_patch','status':'executed','input_hash':digest(data),'output_hash':digest(path.read_bytes())}
        self.receipts[key]=receipt; self.stage=Stage.PATCHED
        (self.root/'receipts.json').write_text(json.dumps(self.receipts,indent=2))
        return receipt
    def check(self,passed):
        self.tick()
        if self.stage!=Stage.PATCHED: raise RuntimeError('invalid gate transition')
        self.stage=Stage.CHECKED if passed else Stage.BLOCKED
        return {'gate':'provided_fixture_assertion','passed':passed,'production_test':False}
    def report(self):
        self.tick()
        if self.stage!=Stage.CHECKED: raise RuntimeError('failed or missing gate')
        self.stage=Stage.REPORT
        return {'stage':self.stage.value,'deployment':'not performed','receipts':self.receipts}
if __name__=='__main__':
    with tempfile.TemporaryDirectory() as temp:
        root=Path(temp); (root/'Fixture.java').write_text('class Fixture { int value() { return 1; } }')
        flow=Workflow(root); proposal=flow.plan(); flow.approve(proposal.digest())
        first=flow.apply(); assert flow.apply()==first
        flow.check('return 2;' in (root/'Fixture.java').read_text()); print(json.dumps(flow.report(),indent=2))
        try: flow.file('../secret')
        except PermissionError: pass
        else: raise AssertionError('path escape accepted')
        (root/'Fixture.java').write_text('class Fixture { int value() { return 1; } }')
        bad=Workflow(root); p=bad.plan(); bad.approve(p.digest())
        bad.proposal=Proposal(p.path,p.before,'return 9;',p.source_hash)
        try: bad.apply()
        except PermissionError: pass
        else: raise AssertionError('stale approval accepted')
        fail=Workflow(root); p=fail.plan(); fail.approve(p.digest()); fail.apply(); fail.check(False)
        try: fail.report()
        except RuntimeError: pass
        else: raise AssertionError('failed gate released')
        print('path, stale approval, replay and failed gate checks passed')

from __future__ import annotations
import hashlib,json,math,statistics
from dataclasses import asdict,dataclass
@dataclass(frozen=True)
class Bundle:
    version: str
    mean: float
    scale: float
    weight: float
    bias: float
    data_id: str='synthetic-fixture-v1'
    def manifest(self):
        value=asdict(self); value['schema']={'build_minutes':'finite float >= 0'}
        value['artifact_hash']=hashlib.sha256(json.dumps(value,sort_keys=True).encode()).hexdigest()
        return value
V1=Bundle('bundle-v1',4.,2.,.5,-.3)
V2=Bundle('bundle-v2',5.,3.,.7,-.2)
def preprocess(payload,bundle):
    if set(payload)!={'build_minutes'}: raise ValueError('input schema mismatch')
    value=payload['build_minutes']
    if isinstance(value,bool) or not isinstance(value,(float,int)) or not math.isfinite(value) or value<0:
        raise ValueError('invalid duration')
    if not math.isfinite(bundle.scale) or bundle.scale<=0: raise ValueError('invalid preprocessing bundle')
    return (value-bundle.mean)/bundle.scale

def predict(payload,bundle=V1):
    z=bundle.weight*preprocess(payload,bundle)+bundle.bias
    probability=1/(1+math.exp(-max(-700,min(700,z))))
    return {'risk_probability':probability,'bundle_version':bundle.version,
            'artifact_hash':bundle.manifest()['artifact_hash'],'synthetic':True}
class Registry:
    def __init__(self): self.active=V1; self.previous=None
    def promote(self,bundle,gate_passed):
        if not gate_passed: raise RuntimeError('promotion gate failed')
        self.previous,self.active=self.active,bundle
    def rollback(self):
        if self.previous is None: raise RuntimeError('no prior bundle')
        self.active,self.previous=self.previous,None

def drift(reference,current):
    if len(reference)<2 or len(current)<2: raise ValueError('insufficient samples')
    scale=statistics.stdev(reference)
    if scale==0: raise ValueError('constant reference needs another drift statistic')
    shift=abs(statistics.mean(current)-statistics.mean(reference))/scale
    return {'normalized_mean_shift':shift,'alarm':shift>2.,'labels_present':False,
            'claim':'input shift proxy; performance loss unassessed'}
if __name__=='__main__':
    payload={'build_minutes':6.}; serving=predict(payload,V1)
    offline=1/(1+math.exp(-(V1.weight*preprocess(payload,V1)+V1.bias)))
    assert math.isclose(serving['risk_probability'],offline,abs_tol=1e-12)
    for invalid in [{},{'build_minutes':float('nan')},{'build_minutes':-1},{'build_minutes':True},{'build_minutes':3,'tenant':'x'}]:
        try: predict(invalid)
        except ValueError: pass
        else: raise AssertionError('invalid schema accepted')
    registry=Registry(); before=predict(payload,registry.active)
    registry.promote(V2,True); assert predict(payload,registry.active)!=before
    registry.rollback(); assert predict(payload,registry.active)==before
    try: registry.promote(V2,False)
    except RuntimeError: pass
    else: raise AssertionError('failed promotion accepted')
    print(json.dumps({'manifest':V1.manifest(),'prediction':before,
                     'drift':drift([2,3,4,5,6],[12,13,14,15,16])},indent=2))
    print('schema, parity, promotion and full-bundle rollback checks passed')

