from __future__ import annotations
import hashlib,json,shutil,subprocess,tempfile
from pathlib import Path

def sha(data): return hashlib.sha256(data).hexdigest()
def execute(action,root):
    commands={'compile_java8':['javac','--release','8','QuoteFixture.java'],
              'compile_java17':['javac','--release','17','QuoteFixture.java'],
              'java_version':['java','-version'],
              'test_java':['java','-cp',str(root),'QuoteFixture']}
    if action not in commands: raise PermissionError('unsupported tool action')
    cmd=commands[action]
    if shutil.which(cmd[0]) is None:
        return {'action':action,'status':'not_executed','reason':'JDK tool not installed'}
    try:
        result=subprocess.run(cmd,cwd=root,timeout=15,capture_output=True,text=True)
    except subprocess.TimeoutExpired:
        return {'action':action,'status':'failed','reason':'timeout; reconcile workspace before retry'}
    stdout=result.stdout[:8192]; stderr=result.stderr[:8192]
    return {'action':action,'status':'executed' if result.returncode==0 else 'failed',
            'exit_code':result.returncode,'stdout':stdout,'stderr':stderr,
            'stdout_hash':sha(stdout.encode()),'stderr_hash':sha(stderr.encode())}

def java_gate(root,compile_action):
    compile_receipt=execute(compile_action,root)
    receipts=[compile_receipt]
    if compile_receipt['status']=='executed':
        test_receipt=execute('test_java',root); receipts.append(test_receipt)
        passed=test_receipt['status']=='executed' and 'PASS 5 Java behavior cases' in test_receipt.get('stdout','')
    else: passed=False
    return passed,receipts

def apply(path,before,after,approved_hash):
    current=path.read_bytes()
    proposed={'path':path.name,'input_hash':sha(current),'before':before,'after':after}
    expected=sha(json.dumps(proposed,sort_keys=True).encode())
    if approved_hash!=expected: raise PermissionError('approval does not bind proposed patch')
    text=current.decode()
    if text.count(before)!=1: raise ValueError('patch precondition failed')
    output=text.replace(before,after,1).encode(); path.write_bytes(output)
    return {'status':'executed','action':'approved_local_patch','approval_hash':expected,
            'input_hash':sha(current),'output_hash':sha(output)}

def dotnet_adapter_plan(root):
    return {'adapter_language':'python','target_ecosystem':'dotnet',
      'status':'dry_run','execution':'not_executed',
      'capabilities':['inventory','supported_tool_assessment','approved_tool_migration','build','contract_tests'],
      'workspace':str(root),'commands':[['dotnet','--info'],['dotnet','build','--no-restore']],
      'conditions':['supported modernization tool installed and pinned','source/target compatibility reviewed',
                    'isolated workspace','approved exact patch','no secrets or unauthorized egress'],
      'receipt_required':['tool_version','input_revision','scope_hash','exit_status','artifact_hash','gate_results']}
if __name__=='__main__':
    source=Path(__file__).with_name('QuoteFixture.java')
    with tempfile.TemporaryDirectory(prefix='bootcamp-java-') as temp:
        root=Path(temp); path=root/'QuoteFixture.java'; shutil.copyfile(source,path)
        baseline_ok,baseline=java_gate(root,'compile_java8')
        report={'scope':'Java 8 to 17 compiler-target upgrade plus local null-check recipe',
                'source_target':{'before_release':8,'after_release':17,'runtime_execution':'same installed JDK; not separate Java 8/17 runtime certification'},
                'installed_runtime':execute('java_version',root),'baseline':baseline,
                'dotnet':dotnet_adapter_plan(root),'deployment':'not performed'}
        before='if (value == null) throw new IllegalArgumentException("value required");'
        after='if (java.util.Objects.isNull(value)) throw new IllegalArgumentException("value required");'
        proposal={'path':path.name,'input_hash':sha(path.read_bytes()),'before':before,'after':after}
        approval=sha(json.dumps(proposal,sort_keys=True).encode())
        if baseline_ok:
            report['patch']=apply(path,before,after,approval)
            post_ok,post=java_gate(root,'compile_java17'); report['post_transform']=post
            report['covered_parity_passed']=post_ok
            assert post_ok
            try: apply(path,after,before,approval)
            except PermissionError: report['stale_approval_rejected']=True
            else: raise AssertionError('changed artifact accepted stale approval')
        else:
            report['patch']={'status':'not_executed','reason':'baseline unavailable or failed'}
        print(json.dumps(report,indent=2))

import json,sys
DOMAINS=['Python','Statistics','ML','Deep Learning','NLP','LLM','Prompt Engineering','RAG',
         'AI Agents','MLOps','Cloud AI','DevOps','Java','Modernization','AI Security',
         'System Design','Leadership']
CRITICAL={'Python','ML','RAG','AI Agents','AI Security','Modernization'}
REQUIRED_BOUNDARIES=('tenant_isolation','tool_authorization','leakage_control','approval_binding')
def assess(data):
    scores=data.get('scores',{}); boundaries=data.get('critical_boundaries',{})
    if set(scores)-set(DOMAINS): raise ValueError('unknown scoring domain')
    if not isinstance(data.get('source'),str) or not data['source'].strip(): raise ValueError('score provenance required')
    assessed={}; unknown=[]
    for domain in DOMAINS:
        entry=scores.get(domain)
        if entry is None or entry.get('score') is None:
            unknown.append(domain); continue
        score=entry['score']
        if isinstance(score,bool) or not isinstance(score,(int,float)) or not 0<=score<=100:
            raise ValueError('invalid score')
        if not isinstance(entry.get('evidence'),list) or not entry['evidence']:
            unknown.append(domain); continue
        assessed[domain]=score
    for value in boundaries.values():
        if value not in ['passed','failed','unassessed']: raise ValueError('invalid boundary state')
    failed=[name for name,value in boundaries.items() if value=='failed']
    unknown_boundaries=sorted(set(boundaries)-set(REQUIRED_BOUNDARIES))
    unresolved=[name for name in REQUIRED_BOUNDARIES if boundaries.get(name,'unassessed')!='passed']
    unresolved+=unknown_boundaries
    weak=sorted(assessed,key=lambda d:(0 if d in CRITICAL else 1,assessed[d],d))
    targets=[d for d in weak if assessed[d]<65]+[d for d in unknown if d in CRITICAL]
    targets=list(dict.fromkeys(targets))[:3]
    while len(targets)<3: targets.append(['Capstone defense','Failure tests','Spaced recall'][len(targets)])
    revision=[{'minutes':20,'task':'Recall failed mechanisms without notes'},
      *[{'minutes':60,'task':f'{d}: mechanism 15m, worked example 15m, failure test 20m, closed-book defense 10m'} for d in targets],
      {'minutes':20,'task':'Reassess using actual evidence'},
      {'minutes':20,'task':'Capstone defense and tomorrow checkpoint'}]
    assert sum(x['minutes'] for x in revision)==240
    ready=not unknown and not failed and not unresolved and all(score>=65 for score in assessed.values())
    return {'source':data['source'],'assessment':'deterministic aggregation of human-entered rubric scores',
      'assessed_domains':len(assessed),'total_domains':len(DOMAINS),'unassessed':unknown,
      'mean_assessed':sum(assessed.values())/len(assessed) if assessed else None,
      'critical_failures':failed,'unresolved_boundaries':unresolved,
      'unknown_boundaries':unknown_boundaries,
      'readiness':'local rubric criteria met; not hiring certification' if ready else 'needs evidence or revision',
      'revision_240_minutes':revision}
if __name__=='__main__':
    if len(sys.argv)>1:
        data=json.load(open(sys.argv[1]))
    else:
        data={'source':'synthetic self-assessment example',
              'scores':{'Python':{'score':70,'evidence':['example receipt, replace with yours']},
                        'AI Security':{'score':90,'evidence':['example review, replace with yours']}},
              'critical_boundaries':{'tool_authorization':'failed'}}
    result=assess(data)
    if len(sys.argv)==1:
        assert len(result['unassessed'])==15
        assert result['readiness']=='needs evidence or revision'
        assert result['critical_failures']==['tool_authorization']
        complete={'source':'fixture self-test',
                  'scores':{d:{'score':80,'evidence':['fixture-only']} for d in DOMAINS},
                  'critical_boundaries':{b:'passed' for b in REQUIRED_BOUNDARIES}}
        assert assess(complete)['readiness'].startswith('local rubric criteria met')
        for status in ['failed','unassessed','passed']:
            extra={**complete,'critical_boundaries':{**complete['critical_boundaries'],'egress_policy':status}}
            blocked=assess(extra)
            assert blocked['readiness']=='needs evidence or revision'
            assert blocked['unknown_boundaries']==['egress_policy']
            assert 'egress_policy' in blocked['unresolved_boundaries']
        for boundary in REQUIRED_BOUNDARIES:
            missing={**complete,'critical_boundaries':{k:v for k,v in complete['critical_boundaries'].items() if k!=boundary}}
            assert assess(missing)['readiness']=='needs evidence or revision'
            failed={**complete,'critical_boundaries':{**complete['critical_boundaries'],boundary:'failed'}}
            assert assess(failed)['readiness']=='needs evidence or revision'
    print(json.dumps(result,indent=2))

